// Scenarios (DESIGN §19): established co-ops handed to the player at a turning point. The
// co-op's history is generated by running the prudent baseline GM from an earlier year with a
// fixed seed, so it arrives with real annual reports, members, directors and a balance sheet.

export type ScenarioGoal =
  | { kind: 'survive'; label: string }
  | { kind: 'standing'; label: string }
  | { kind: 'equityRatio'; label: string; min: number }
  | { kind: 'locations'; label: string; min: number }
  | { kind: 'merger'; label: string }
  | { kind: 'grainGrowth'; label: string; min: number }
  | { kind: 'savingsYears'; label: string; years: number };

export interface ScenarioDef {
  id: string;
  title: string;
  year: number;
  /** One-line teaser for the picker. */
  teaser: string;
  /** The briefing memo that opens the game. */
  briefing: string;
  /** History run before the player takes over. */
  history: { fromYear: number; seed: number; mapSeed: number; members: number; capital: 'typical' | 'well' };
  /** The goals are judged in January of this year. */
  deadlineYear: number;
  goals: ScenarioGoal[];
  /** Neighboring co-ops start weak (merger wave). */
  weakNeighbors?: boolean;
}

